/**
 * Offline mutation queue.
 *
 * createQueue({ send, storage, isOnline })
 *   - send(mutation)      -> Promise, posts ONE mutation
 *   - storage             -> localStorage-shaped: getItem/setItem/removeItem
 *   - isOnline()          -> injected predicate
 *
 * State is persisted as JSON under the key "queue:v1":
 *   { pending: [{ id, mutation, attempts }], deadLetters: [...], nextId }
 *
 * Semantics:
 *   - enqueue(mutation): assigns a monotonic id; if online, sends immediately,
 *     otherwise persists and waits for flush().
 *   - flush(): drains pending FIFO, stopping at the first failure. The failed
 *     entry (attempts incremented) and everything after it stay persisted.
 *     An entry reaching MAX_ATTEMPTS failed sends is promoted to deadLetters.
 *   - goingOnline(): triggers a flush.
 */

const STORAGE_KEY = 'queue:v1';
const MAX_ATTEMPTS = 3;

export function createQueue({ send, storage, isOnline }) {
  if (typeof send !== 'function') throw new Error('createQueue: send is required');
  if (!storage || typeof storage.getItem !== 'function' || typeof storage.setItem !== 'function') {
    throw new Error('createQueue: localStorage-shaped storage is required');
  }

  let state = rehydrate();

  function rehydrate() {
    const raw = storage.getItem(STORAGE_KEY);
    if (raw) {
      try {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === 'object') {
          return {
            pending: Array.isArray(parsed.pending) ? parsed.pending : [],
            deadLetters: Array.isArray(parsed.deadLetters) ? parsed.deadLetters : [],
            nextId: Number.isInteger(parsed.nextId) && parsed.nextId > 0 ? parsed.nextId : 1,
          };
        }
      } catch {
        // Corrupt payload: start fresh rather than crash on boot.
      }
    }
    return { pending: [], deadLetters: [], nextId: 1 };
  }

  function persist() {
    storage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  /**
   * Send a single pending entry. Returns true on success. On failure:
   * increments attempts, promotes to the dead-letter list at MAX_ATTEMPTS.
   */
  async function attemptHead() {
    const entry = state.pending[0];
    try {
      await send(entry.mutation);
      state.pending.shift();
      persist();
      return true;
    } catch {
      entry.attempts += 1;
      if (entry.attempts >= MAX_ATTEMPTS) {
        state.pending.shift();
        state.deadLetters.push(entry);
      }
      persist();
      return false;
    }
  }

  return {
    /** Queue a mutation. Sends immediately when online, else persists only. */
    async enqueue(mutation) {
      const entry = { id: state.nextId++, mutation, attempts: 0 };
      state.pending.push(entry);
      persist();

      if (isOnline()) {
        // Drain (covers the just-enqueued item plus any backlog).
        while (state.pending.length > 0 && isOnline()) {
          const ok = await attemptHead();
          if (!ok) break; // first failure halts the drain
        }
      }
      return entry.id;
    },

    /** Drain pending mutations FIFO; stop at the first failure. */
    async flush() {
      while (state.pending.length > 0 && isOnline()) {
        const ok = await attemptHead();
        if (!ok) break;
      }
    },

    /** Connectivity restored hook: kick off a drain. */
    async goingOnline() {
      await this.flush();
    },

    /** Snapshot of dead-lettered entries ({ id, mutation, attempts }). */
    deadLetters() {
      return state.deadLetters.map((e) => ({ ...e, mutation: e.mutation }));
    },

    /** Current pending snapshot (useful for tests/debugging). */
    pending() {
      return state.pending.map((e) => ({ ...e }));
    },
  };
}

export { STORAGE_KEY, MAX_ATTEMPTS };

