import { describe, it, expect, vi } from 'vitest';
import { createQueue, STORAGE_KEY, MAX_ATTEMPTS } from '../src/queue.js';

/** In-memory localStorage-shaped storage. */
function createMemoryStorage(seed = {}) {
  const map = new Map(Object.entries(seed));
  return {
    getItem: (k) => (map.has(k) ? map.get(k) : null),
    setItem: (k, v) => map.set(k, String(v)),
    removeItem: (k) => map.delete(k),
    dump: () => Object.fromEntries(map),
  };
}

/** Scriptable send stub: outcomes are consumed per call — a value resolves, an Error rejects. */
function createSendStub(outcomes = []) {
  const calls = [];
  const fn = vi.fn(async (mutation) => {
    calls.push(mutation);
    if (outcomes.length === 0) return { ok: true };
    const outcome = outcomes.shift();
    if (outcome instanceof Error) throw outcome;
    return outcome;
  });
  fn.calls = calls;
  fn.push = (...o) => outcomes.push(...o);
  return fn;
}

describe('createQueue', () => {
  it('sends immediately when online', async () => {
    const storage = createMemoryStorage();
    const send = createSendStub();
    const queue = createQueue({ send, storage, isOnline: () => true });

    const id = await queue.enqueue({ type: 'CREATE_POST', title: 'hello' });

    expect(id).toBe(1);
    expect(send).toHaveBeenCalledTimes(1);
    expect(send.calls[0]).toEqual({ type: 'CREATE_POST', title: 'hello' });
    expect(queue.pending()).toEqual([]);
    // Successful send leaves nothing persisted under queue:v1's pending list.
    const persisted = JSON.parse(storage.getItem(STORAGE_KEY));
    expect(persisted.pending).toEqual([]);
  });

  it('persists offline enqueues and flushes them FIFO once online', async () => {
    const storage = createMemoryStorage();
    let online = false;
    const send = createSendStub();
    const queue = createQueue({ send, storage, isOnline: () => online });

    await queue.enqueue({ op: 'a' });
    await queue.enqueue({ op: 'b' });
    await queue.enqueue({ op: 'c' });
    expect(send).not.toHaveBeenCalled();

    // Persisted while offline.
    const persisted = JSON.parse(storage.getItem(STORAGE_KEY));
    expect(persisted.pending.map((e) => e.mutation.op)).toEqual(['a', 'b', 'c']);

    online = true;
    await queue.flush();

    expect(send.calls.map((m) => m.op)).toEqual(['a', 'b', 'c']);
    expect(queue.pending()).toEqual([]);
  });

  it('flush stops at the first failure and leaves remaining entries persisted', async () => {
    const storage = createMemoryStorage();
    let online = true;
    const send = createSendStub([new Error('network down')]);
    const queue = createQueue({ send, storage, isOnline: () => online });

    await queue.enqueue({ op: 'first' }); // sent immediately, succeeds
    send.push(new Error('flaky'));
    online = false;
    await queue.enqueue({ op: 'second' });
    await queue.enqueue({ op: 'third' });

    online = true;
    await queue.flush(); // 'second' fails once

    expect(send.calls.map((m) => m.op)).toEqual(['first', 'second']);
    const pending = queue.pending();
    expect(pending.map((e) => e.mutation.op)).toEqual(['second', 'third']); // failed one stays head
    expect(pending[0].attempts).toBe(1);
    expect(pending[0].id).toBe(2);
    expect(pending[1].attempts).toBe(0);

    // State consistent with what's on disk.
    const persisted = JSON.parse(storage.getItem(STORAGE_KEY));
    expect(persisted.pending.map((e) => e.mutation.op)).toEqual(['second', 'third']);

    // Retry after recovery drains the rest in order.
    await queue.flush();
    expect(send.calls.map((m) => m.op)).toEqual(['first', 'second', 'third']);
    expect(queue.pending()).toEqual([]);
  });

  it('promotes an entry to dead letters after MAX_ATTEMPTS failures', async () => {
    const storage = createMemoryStorage();
    let online = false;
    const alwaysFail = new Error('nope');
    const send = createSendStub([alwaysFail, alwaysFail]);
    const queue = createQueue({ send, storage, isOnline: () => online });

    const poisonId = await queue.enqueue({ op: 'poison' });
    await queue.enqueue({ op: 'after' });

    online = true;
    await queue.flush(); // failure #1 -> attempts=1, stays pending
    await queue.flush(); // failure #2 -> attempts=2, stays pending
    send.push(alwaysFail); // failure #3 will be the last scripted outcome
    await queue.flush(); // failure #3 -> dead letter

    const letters = queue.deadLetters();
    expect(letters).toHaveLength(1);
    expect(letters[0].id).toBe(poisonId);
    expect(letters[0].mutation.op).toBe('poison');
    expect(letters[0].attempts).toBe(MAX_ATTEMPTS);

    // The poisoned head was removed; the follower remains queued.
    expect(queue.pending().map((e) => e.mutation.op)).toEqual(['after']);
    const persisted = JSON.parse(storage.getItem(STORAGE_KEY));
    expect(persisted.deadLetters.map((e) => e.id)).toEqual([poisonId]);
    expect(persisted.pending.map((e) => e.mutation.op)).toEqual(['after']);
  });

  it('rehydrates a persisted queue from storage and continues ids monotonically', async () => {
    const seededPending = [
      { id: 41, mutation: { op: 'old-a' }, attempts: 0 },
      { id: 42, mutation: { op: 'old-b' }, attempts: 2 },
    ];
    const storage = createMemoryStorage({
      [STORAGE_KEY]: JSON.stringify({
        pending: seededPending,
        deadLetters: [{ id: 7, mutation: { op: 'dead' }, attempts: 3 }],
        nextId: 43,
      }),
    });

    const send = createSendStub();
    const queue = createQueue({ send, storage, isOnline: () => true });

    // Resumed backlog is visible without any new enqueues.
    expect(queue.pending().map((e) => e.id)).toEqual([41, 42]);

    // New mutations continue the monotonic sequence across restarts.
    const newId = await queue.enqueue({ op: 'new-c' });
    expect(newId).toBe(43);

    await queue.flush();
    // FIFO order preserved across rehydration: old items first, then the new one.
    expect(send.calls.map((m) => m.op)).toEqual(['old-a', 'old-b', 'new-c']);

    // Dead letters survived the restart untouched.
    expect(queue.deadLetters().map((e) => e.mutation.op)).toEqual(['dead']);

    const persisted = JSON.parse(storage.getItem(STORAGE_KEY));
    expect(persisted.nextId).toBe(44);
  });

  it('goingOnline triggers a flush of the persisted backlog', async () => {
    const storage = createMemoryStorage();
    let online = false;
    const send = createSendStub();
    const queue = createQueue({ send, storage, isOnline: () => online });

    await queue.enqueue({ op: 'queued-while-offline' });
    expect(send).not.toHaveBeenCalled();

    online = true;
    await queue.goingOnline();

    expect(send.calls.map((m) => m.op)).toEqual(['queued-while-offline']);
    expect(queue.pending()).toEqual([]);
  });
});

